content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Receptionist",
      "description": "Handles guest bookings, check-ins, check-outs, and communication with housekeeping."
    },
    {
      "name": "Guest",
      "description": "A hotel customer who books, stays, and requests services."
    },
    {
      "name": "Booking",
      "description": "A reservation made by a guest for a specific room and duration.",
      "attributes": [
        "Room",
        "Duration"
      ]
    },
    {
      "name": "Room",
      "description": "A hotel accommodation unit assigned to a booking or cleaning task.",
      "attributes": [
        "Completion Status"
      ]
    },
    {
      "name": "Duration",
      "description": "The time span of a guest’s stay as defined in the booking."
    },
    {
      "name": "Service Request",
      "description": "A request from a guest for an additional service or assistance."
    },
    {
      "name": "Check In",
      "description": "The process of registering a guest’s arrival and granting room access.",
      "attributes": [
        "Room Access Information"
      ]
    },
    {
      "name": "Room Access Information",
      "description": "Details that allow a guest to access their assigned room, such as key code or card."
    },
    {
      "name": "Check Out",
      "description": "The process of a guest’s departure and closing of their stay record."
    },
    {
      "name": "Feedback",
      "description": "Guest comments or evaluations about their stay experience."
    },
    {
      "name": "Housekeeping Supervisor",
      "description": "Oversees room cleaning, schedules tasks, and reports issues to reception."
    },
    {
      "name": "Cleaning Schedule",
      "description": "A daily plan that assigns cleaners to specific rooms.",
      "attributes": [
        "Cleaner"
      ]
    },
    {
      "name": "Cleaner",
      "description": "A staff member responsible for cleaning and preparing guest rooms.",
      "attributes": [
        "Room"
      ]
    },
    {
      "name": "Completion Status",
      "description": "Indicates whether a room is ready, occupied, or needs cleaning."
    },
    {
      "name": "Issue Report",
      "description": "A note raised by housekeeping about room-related problems or maintenance needs."
    }
  ]
}
```
